class MakeChessLocalizationController {
  MakeChessLocalizationController._();

  static final ValueNotifier<String> languageCode = ValueNotifier<String>('RU');

  static String get currentCode => languageCode.value;

  static void setLanguage(String code) {
    final normalized = code.trim().toUpperCase();
    final safeCode = kMakeChessSupportedLanguageCodes.contains(normalized)
        ? normalized
        : 'RU';
    if (languageCode.value != safeCode) {
      languageCode.value = safeCode;
    }
  }
}

