  final Color? selectionColor;

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<String>(
      valueListenable: MakeChessLocalizationController.languageCode,
      builder: (context, languageCode, child) {
        if (textSpan != null) {
          return Text.rich(
            textSpan!,
