  static String normalizeLanguageCode(String? code) {
    final normalized = (code ?? 'RU').trim().toUpperCase();
    return kMakeChessSupportedLanguageCodes.contains(normalized)
        ? normalized
        : 'RU';
  }

  static MakeChessLanguage language(String? code) {
    final normalized = normalizeLanguageCode(code);
    return kMakeChessLanguages.firstWhere(
      (item) => item.code == normalized,
      orElse: () => kMakeChessLanguages.first,
    );
  }

  static bool isRtl(String? code) => language(code).rtl;

  static TextDirection textDirection(String? code) =>
      isRtl(code) ? TextDirection.rtl : TextDirection.ltr;

  static String phrase(
    String russian, {
    String? languageCode,
    Map<String, Object?> params = const <String, Object?>{},
  }) {
    final code = normalizeLanguageCode(
      languageCode ?? MakeChessLocalizationController.currentCode,
    );

    String? value;

    final v4Row = _v4PhraseRows[russian];
    if (v4Row != null) {
      final index = _v4LanguageOrder.indexOf(code);
      if (index >= 0 && index < v4Row.length) {
        value = v4Row[index];
      }
    }

    value ??= _phraseTranslations[code]?[russian];

    // Reuse the older key-based central dictionary when a legacy phrase
    // exactly matches the Russian value of an existing MakeChessTextKey.
    if (value == null) {
      String? matchedKey;
      for (final entry in (_translations['RU'] ?? const <String, String>{}).entries) {
        if (entry.value == russian) {
          matchedKey = entry.key;
          break;
        }
      }
      if (matchedKey != null) {
        value = _translations[code]?[matchedKey] ??
            _translations['RU']?[matchedKey];
      }
    }

    value ??= _phraseTranslations['EN']?[russian] ?? russian;

    for (final entry in params.entries) {
      value = value.replaceAll('{${entry.key}}', '${entry.value ?? ''}');
    }
    return value;
  }

  static String text(
    String key, {
    String? languageCode,
    Map<String, Object?> params = const <String, Object?>{},
  }) {
    final code = normalizeLanguageCode(
      languageCode ?? MakeChessLocalizationController.currentCode,
    );
    var value =
        _translations[code]?[key] ?? _translations['RU']?[key] ?? '⟦$key⟧';

    for (final entry in params.entries) {
      value = value.replaceAll('{${entry.key}}', '${entry.value ?? ''}');
    }
    return value;
  }

  static void validateOrThrow() {
    final languageCodes = kMakeChessLanguages.map((e) => e.code).toSet();
    final declaredCodes = kMakeChessSupportedLanguageCodes.toSet();
    if (languageCodes.length != kMakeChessLanguages.length ||
        languageCodes.length != declaredCodes.length ||
        !languageCodes.containsAll(declaredCodes)) {
      throw StateError(
        'MakeChess localization: language list contains duplicates or mismatches.',
      );
    }

    for (final code in kMakeChessSupportedLanguageCodes) {
      final table = _translations[code];
      if (table == null) {
        throw StateError(
          'MakeChess localization: translation table $code is missing.',
        );
      }
      final missing = MakeChessTextKey.all.difference(table.keys.toSet());
      final extra = table.keys.toSet().difference(MakeChessTextKey.all);
      if (missing.isNotEmpty || extra.isNotEmpty) {
        throw StateError(
          'MakeChess localization $code: missing=$missing, extra=$extra',
        );
      }
    }
  }
}
